script:
html { scroll-behavior: smooth; }
::selection { background: #232220; color: #FDFCF8; }

/* the hero receipt feeds out of the printer slot on load */
html.ch-js .ch-feed > * { transform: translateY(-104%); }
html.ch-js.ch-printed .ch-feed > * {
  transform: none;
  transition: transform 2.1s cubic-bezier(0.25, 1, 0.4, 1);
}

html.ch-js .ch-rise { opacity: 0; transform: translateY(16px); }
html.ch-js .ch-rise.ch-in {
  opacity: 1; transform: none;
  transition: opacity 0.8s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.8s cubic-bezier(0.22, 1, 0.36, 1);
}

.ch-ul {
  background-image: linear-gradient(currentColor, currentColor);
  background-position: left bottom; background-repeat: no-repeat;
  background-size: 0% 1.5px;
  transition: background-size 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}
.ch-ul:hover { background-size: 100% 1.5px; }
.ch-btn { transition: opacity 0.2s ease; }
.ch-btn:hover { opacity: 0.82; }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}
